<script setup lang="ts">
import Pagination from '../../shared/components/Pagination.vue'
import { onMounted } from 'vue'
import { useWorkspace } from '../../app/workspace'
const { caseTotal, evidenceTotal, page, intelligence, can } = useWorkspace()
const { myPage,reviewPage,myTasks, myTotal, mineLoading, mineError, loadMine, reviewTasks, reviewTotal, reviewLoading, reviewError, loadReviewQueue } = intelligence
const taskStatus: Record<string,string> = {OPEN:'待办理',RETURNED:'已退回',PENDING_REVIEW:'待复核',CLOSED:'已关闭'}
onMounted(() => { if(can('intelligence.read')){void loadMine(); void loadReviewQueue()} })
</script>

<template>
<div class="metrics"><div v-if="can('cases.read')" class="card"><span>案件草稿</span><strong>{{caseTotal}}</strong><small>当前查询结果总数</small></div><div v-if="can('evidence.read')" class="card"><span>证物对象</span><strong>{{evidenceTotal}}</strong><small>含分样的授权范围总数</small></div></div><section v-if="can('intelligence.read')" class="card intro"><h2>我的核查工单</h2><p class="muted">当前登录人承办且未关闭的工单，按办理期限排序；每页显示 5 条，打开情报线索可查看详情。</p><p v-if="mineLoading" role="status">正在加载待办…</p><p v-else-if="mineError" class="error" role="alert">{{mineError}} <button class="link" @click="loadMine()">重试</button></p><p v-else-if="!myTasks.length" class="empty">暂无待办</p><div v-else class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>线索</th><th>工单状态</th><th>办理期限</th></tr></thead><tbody><tr v-for="(task, rowIndex) in myTasks" :key="task.id"><td class="row-number">{{(myPage-1)*5+rowIndex+1}}</td><td>{{task.clue_title}}</td><td>{{taskStatus[task.status] || '未知状态'}}</td><td>{{task.due_date || '未设置'}}</td></tr></tbody></table><p class="muted">共 {{myTotal}} 条；列表仅含当前组织且当前账号承办的工单。</p></div><Pagination :page="myPage" :total="myTotal" :page-size="5" :loading="mineLoading" @change="loadMine($event)" /><button class="secondary" @click="page='情报线索'">进入情报线索</button></section><section v-if="can('intelligence.read')" class="card intro"><h2>待我复核</h2><p class="muted">本组织中由其他用户提交、处于待复核状态的工单；每页显示 5 条，正式岗位授权尚未实现。</p><p v-if="reviewLoading" role="status">正在加载…</p><p v-else-if="reviewError" class="error" role="alert">{{reviewError}} <button class="link" @click="loadReviewQueue()">重试</button></p><p v-else-if="!reviewTasks.length" class="empty">暂无待复核工单</p><div v-else class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>线索</th><th>状态</th></tr></thead><tbody><tr v-for="(task, rowIndex) in reviewTasks" :key="task.id"><td class="row-number">{{(reviewPage-1)*5+rowIndex+1}}</td><td>{{task.clue_title}}</td><td>待复核</td></tr></tbody></table><p class="muted">共 {{reviewTotal}} 条；进入情报线索后查看详情。</p></div><Pagination :page="reviewPage" :total="reviewTotal" :page-size="5" :loading="reviewLoading" @change="loadReviewQueue($event)" /><button class="secondary" @click="page='情报线索'">进入情报线索</button></section><div class="card intro"><h2>开始使用</h2><p>可从接警信息转办或直接创建案件草稿，再登记证物和初始重量；可在证物管理中查看流水或进行分样。</p><div class="actions"><button v-if="can('cases.read')" @click="page='案件管理'">进入案件管理</button><button v-if="can('evidence.read')" class="secondary" @click="page='证物管理'">进入证物管理</button></div><p class="muted">人员身份核验、正式审批、审计中心及 AI 等功能仍待建设。</p></div>
</template>
